import sys

mod = 998244353
g = 3

def qpow(a, n):
    x = 1
    a %= mod
    while n > 0:
        if n & 1:
            x = x * a % mod
        a = a * a % mod
        n >>= 1
    return x

def rader(y, length):
    j = length // 2
    for i in range(1, length - 1):
        if i < j:
            y[i], y[j] = y[j], y[i]
        k = length // 2
        while j >= k:
            j -= k
            k //= 2
        if j < k:
            j += k

def NTT(y, length, on):
    rader(y, length)
    h = 2
    while h <= length:
        wn = qpow(g, (mod - 1) // h)
        if on == -1:
            wn = qpow(wn, mod - 2)
        for j in range(0, length, h):
            w = 1
            for k in range(j, j + h // 2):
                u = y[k]
                t = w * y[k + h // 2] % mod
                y[k] = (u + t) % mod
                y[k + h // 2] = (u - t + mod) % mod
                w = w * wn % mod
        h <<= 1
    if on == -1:
        t = qpow(length, mod - 2)
        for i in range(length):
            y[i] = y[i] * t % mod

def main():
    input_data = sys.stdin.read().strip().split()
    n, m = int(input_data[0]), int(input_data[1])
    nn = n // 2
    len_pow = 1
    while len_pow < (9 * nn + 1):
        len_pow <<= 1
    a = [0] * len_pow
    b = [0] * len_pow

    a[0] = 1
    for i in range(m):
        x = int(input_data[2 + i])
        b[x] = 1

    NTT(a, len_pow, 1)
    NTT(b, len_pow, 1)

    for i in range(len_pow):
        if a[i] != 0 and b[i] != 0:
            a[i] = a[i] * qpow(b[i], nn) % mod
        else:
            a[i] = 0

    NTT(a, len_pow, -1)

    ans = 0
    for i in range(len_pow):
        ans = (ans + a[i] * a[i]) % mod
    print((ans + mod) % mod)

if __name__ == "__main__":
    main()

